const rewardsByGroup={API:[['Đề xuất giải pháp kỹ thuật được áp dụng',.5],['Gây sự cố production do lỗi chủ quan',-.8]],CMS:[['Tool/tính năng được phòng ban ghi nhận đặc biệt',.5],['Gây lỗi ảnh hưởng phòng ban do bất cẩn',-.5]],Ads:[['Chủ động phát hiện anomaly trước kinh doanh báo',.5],['Sự cố gián đoạn campaign do lỗi kỹ thuật chủ quan',-.8]],Payment:[['Đề xuất cải tiến kỹ thuật luồng Payment được áp dụng',.5],['Bug production do bỏ sót edge case (lỗi chủ quan)',-1]],'R&D':[['Tư vấn giải pháp được nhóm khác áp dụng hiệu quả',.5],['Kết quả nghiên cứu đưa vào sản phẩm thực tế',1],['Hỗ trợ sai hướng gây ảnh hưởng tiêu cực',-.5]],Leader:[['Thành viên trong nhóm được ghi nhận hoặc thăng cấp',.5],['Nhóm đạt 100% mục tiêu 3 tháng liên tiếp',.5],['Onboard thành công member mới trong 1 tháng',.5]]};
function rewardsFor(group){return rewardsByGroup[group]||[]}
function evalGroup(m){return selectedGroup==='Leader'&&m.leader?'Leader':m.group}
function workload(m){return state[m.id]?.workload||{committed:0,closed:0,committedPoints:0,deliveredPoints:0}}
function workloadResult(m){const w=workload(m),completion=w.committed?Math.min(1,w.closed/w.committed):0,effort=w.committedPoints?Math.min(1,w.deliveredPoints/w.committedPoints):0,kpi=result(m,m.group).score/10;const fairness=(completion*.35+effort*.45+kpi*.2)*10;return {completion,effort,kpi,fairness}}
let demoState={cms:{committed:12,closed:10,committedPoints:60,deliveredPoints:44,kpi:8.8},api:{committed:24,closed:18,committedPoints:60,deliveredPoints:42,kpi:8.8}};
function demoScore(x){const completion=x.committed?Math.min(1,x.closed/x.committed):0,effort=x.committedPoints?Math.min(1,x.deliveredPoints/x.committedPoints):0;return {completion,effort,score:(completion*.35+effort*.45+(x.kpi/10)*.2)*10}}
function renderDemo(){const root=document.querySelector('#demoRoot');if(!root)return;const c=demoScore(demoState.cms),a=demoScore(demoState.api),winner=Math.abs(c.score-a.score)<.05?'Gần như ngang nhau':c.score>a.score?'CMS cao hơn':'API cao hơn';root.innerHTML=`<div class="demo-layout"><div class="demo-controls"><div class="demo-team"><div class="demo-team-title"><span class="group-tag">CMS</span><b>Member mẫu CMS</b></div><div class="demo-fields"><label>Task cam kết<input data-demo="cms" data-key="committed" type="number" min="0" value="${demoState.cms.committed}"></label><label>Task đóng<input data-demo="cms" data-key="closed" type="number" min="0" value="${demoState.cms.closed}"></label><label>Effort giao<input data-demo="cms" data-key="committedPoints" type="number" min="0" value="${demoState.cms.committedPoints}"></label><label>Effort đạt<input data-demo="cms" data-key="deliveredPoints" type="number" min="0" value="${demoState.cms.deliveredPoints}"></label><label>KPI chất lượng<input data-demo="cms" data-key="kpi" type="number" min="0" max="10" step="0.1" value="${demoState.cms.kpi}"></label></div></div><div class="demo-team"><div class="demo-team-title"><span class="group-tag">API</span><b>Member mẫu API</b></div><div class="demo-fields"><label>Task cam kết<input data-demo="api" data-key="committed" type="number" min="0" value="${demoState.api.committed}"></label><label>Task đóng<input data-demo="api" data-key="closed" type="number" min="0" value="${demoState.api.closed}"></label><label>Effort giao<input data-demo="api" data-key="committedPoints" type="number" min="0" value="${demoState.api.committedPoints}"></label><label>Effort đạt<input data-demo="api" data-key="deliveredPoints" type="number" min="0" value="${demoState.api.deliveredPoints}"></label><label>KPI chất lượng<input data-demo="api" data-key="kpi" type="number" min="0" max="10" step="0.1" value="${demoState.api.kpi}"></label></div></div></div><div class="demo-result"><div class="demo-result-head"><span>Fairness score</span><strong>${winner}</strong></div><div class="demo-bars"><div class="demo-bar-row"><span>CMS</span><div class="demo-bar"><i style="width:${c.score*10}%"></i></div><b>${c.score.toFixed(2)}</b></div><div class="demo-bar-row"><span>API</span><div class="demo-bar"><i style="width:${a.score*10}%"></i></div><b>${a.score.toFixed(2)}</b></div></div><div class="demo-formula">35% completion · 45% effort/story point · 20% KPI chất lượng</div><button class="btn btn-ghost" id="demoReset">Khôi phục dữ liệu mẫu</button></div></div>`;root.querySelectorAll('[data-demo]').forEach(i=>i.oninput=()=>{demoState[i.dataset.demo][i.dataset.key]=Number(i.value)||0;renderDemo()});root.querySelector('#demoReset').onclick=()=>{demoState={cms:{committed:12,closed:10,committedPoints:60,deliveredPoints:44,kpi:8.8},api:{committed:24,closed:18,committedPoints:60,deliveredPoints:42,kpi:8.8}};renderDemo()}}
let period=document.querySelector('#period'), selectedGroup='Tất cả', selectedId=null, state={}, currentRole=localStorage.getItem('backend-kpi-role')||'Admin';
period.value=new Date().toISOString().slice(0,7);
function key(){return `backend-kpi-${period.value}`}; function statusKey(){return `${key()}-status`}; function currentStatus(){return localStorage.getItem(statusKey())||'draft'}; function canEdit(){return currentRole!=='Member'&&currentStatus()!=='locked'}; function statusLabel(x){return ({draft:'Nháp',submitted:'Đã gửi',approved:'Đã duyệt',locked:'Đã khóa'})[x]||x}; function load(){try{state=JSON.parse(localStorage.getItem(key())||'{}');members.forEach(m=>{if(state[m.id]?.scores||state[m.id]?.rewards){const old={scores:state[m.id].scores||[],rewards:state[m.id].rewards||[]};state[m.id][m.group]??=old;delete state[m.id].scores;delete state[m.id].rewards}})}catch{state={}};document.querySelector('#roleSelect').value=currentRole;document.querySelector('#statusSelect').value=currentStatus()}; function save(action='Lưu dữ liệu'){state.audit??=[];state.audit.unshift({time:new Date().toLocaleString('vi-VN'),role:currentRole,action,status:currentStatus()});state.audit=state.audit.slice(0,50);localStorage.setItem(key(),JSON.stringify(state));toast(`${action} · ${period.value}`)}
function result(m,forceGroup){const group=typeof forceGroup==='string'?forceGroup:evalGroup(m),g={...groups[group],criteria:criteriaFor(group)}, rewards=rewardsFor(group);const s=state[m.id]||{};const scores=g.criteria.map((c,i)=>Math.min(c[1],Math.max(0,Number(s[group]?.scores?.[i]??0))));const max=g.criteria.reduce((a,c)=>a+c[1],0);const achieved=scores.reduce((a,b)=>a+b,0);const base=achieved/max*10;const bonus=(s[group]?.rewards||[]).reduce((a,n,i)=>a+Number(n||0)*(rewards[i]?.[1]||0),0);const score=Math.max(0,Math.min(10,base+bonus));let grade=score===10?'A+':score>=9.7?'A':score>=9.4?'B+':score>=9?'B':score>=8?'C':score>=7.5?'D':'E';let coef=score===10?1.4:score>=9.7?1.3:score>=9.4?1.2:score>=9?1.1:score>=8?1:score>=7.5?.8:.6;return {scores,max,achieved,base,bonus,score,grade,coef,group}}
function renderTabs(){document.querySelector('#groupTabs').innerHTML=['Tất cả',...Object.keys(groups),'So sánh liên nhóm'].map(x=>`<button class="tab ${x===selectedGroup?'active':''}" data-group="${x}">${x}</button>`).join('');document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{selectedGroup=b.dataset.group;render()})}
function renderStats(list){const rs=list.map(result);const avg=rs.length?rs.reduce((a,r)=>a+r.score,0)/rs.length:0;const leaders=rs.filter(r=>r.grade==='A+'||r.grade==='A').length;document.querySelector('#stats').innerHTML=[['Thành viên',list.length,'Trong phạm vi đang lọc'],['Điểm trung bình',avg.toFixed(2),'/ 10 điểm'],['Nhóm đạt A/A+',leaders,`${leaders?'Có':'Chưa có'} thành viên nổi bật`],['Tổng điểm thưởng/trừ',rs.reduce((a,r)=>a+r.bonus,0).toFixed(2),'Điểm cộng/trừ đã nhập']].map(x=>`<div class="stat"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-note">${x[2]}</div></div>`).join('')}
function renderTable(list){const body=document.querySelector('#rankingBody');const sorted=list.map(m=>({m,r:result(m)})).sort((a,b)=>b.r.score-a.r.score);body.innerHTML=sorted.map(({m,r},i)=>`<tr class="member-row ${m.id===selectedId?'selected':''}" data-id="${m.id}"><td class="rank-no">${i+1}</td><td><span class="member-name">${m.name}</span><span class="member-id">${m.id}</span></td><td><span class="group-tag">${r.group}</span></td><td class="score">${r.score.toFixed(2)}</td><td><span class="grade ${r.grade==='E'?'low':r.grade==='D'?'warn':''}">${r.grade}</span></td><td class="coefficient">${r.coef.toFixed(1)}</td><td class="bonus ${r.bonus>0?'positive':r.bonus<0?'negative':''}">${r.bonus>0?'+':''}${r.bonus.toFixed(2)}</td></tr>`).join('');body.querySelectorAll('tr').forEach(row=>row.onclick=()=>{selectedId=row.dataset.id;render()});document.querySelector('#memberCount').textContent=`${list.length} member`}
function renderWorkloadEditor(){const empty=document.querySelector('#editorEmpty'),el=document.querySelector('#editor'),m=members.find(x=>x.id===selectedId);if(!m){empty.classList.remove('hidden');el.classList.add('hidden');return}empty.classList.add('hidden');el.classList.remove('hidden');const w=workload(m),r=workloadResult(m);document.querySelector('#editorTitle').textContent=`Workload · ${m.name}`;document.querySelector('#editorMeta').textContent=`${m.id} · ${m.group} · Điểm công bằng ${r.fairness.toFixed(2)}/10`;el.innerHTML=`<div class="editor-body"><div class="help">Không so sánh bằng số task thô. Nhập cả số task và effort/story point để phản ánh độ khó.</div><div class="workload-grid"><label>Task cam kết<input class="count-input" data-work="committed" type="number" min="0" value="${w.committed}"></label><label>Task đã đóng<input class="count-input" data-work="closed" type="number" min="0" value="${w.closed}"></label><label>Effort cam kết<input class="count-input" data-work="committedPoints" type="number" min="0" step="0.1" value="${w.committedPoints}"></label><label>Effort đạt<input class="count-input" data-work="deliveredPoints" type="number" min="0" step="0.1" value="${w.deliveredPoints}"></label></div><div class="formula-note"><b>Fairness score</b> = 35% tỷ lệ task hoàn thành + 45% tỷ lệ effort đạt + 20% KPI chất lượng</div><button class="btn btn-primary save-inline" id="saveWorkload">Lưu workload</button></div>`;el.querySelectorAll('[data-work]').forEach(inp=>inp.onchange=()=>{state[m.id]??={};state[m.id].workload??={};state[m.id].workload[inp.dataset.work]=Number(inp.value)||0;render()});el.querySelector('#saveWorkload').onclick=save}
function renderComparison(){document.querySelector('#tableHead').innerHTML='<tr><th>#</th><th>Member</th><th>Team</th><th>Task đóng / cam kết</th><th>Effort giao / đạt</th><th>Hoàn thành</th><th>Fairness score</th></tr>';const body=document.querySelector('#rankingBody');const sorted=members.map(m=>({m,r:workloadResult(m)})).sort((a,b)=>b.r.fairness-a.r.fairness);body.innerHTML=sorted.map(({m,r},i)=>{const w=workload(m);return `<tr class="member-row ${m.id===selectedId?'selected':''}" data-id="${m.id}"><td class="rank-no">${i+1}</td><td><span class="member-name">${m.name}</span><span class="member-id">${m.id}</span></td><td><span class="group-tag">${m.group}</span></td><td>${w.closed} / ${w.committed}</td><td>${w.deliveredPoints} / ${w.committedPoints}</td><td>${(r.completion*100).toFixed(0)}%</td><td class="score">${r.fairness.toFixed(2)}</td></tr>`}).join('');body.querySelectorAll('tr').forEach(row=>row.onclick=()=>{selectedId=row.dataset.id;render()});document.querySelector('#memberCount').textContent=`${members.length} member`;renderWorkloadEditor()}
function renderFormulaBreakdown(){const m=members.find(x=>x.id===selectedId),box=document.querySelector('#editor .summary-box');if(!m||!box||selectedGroup==='So sánh liên nhóm')return;const r=result(m),node=document.createElement('div');node.className='formula-breakdown';node.innerHTML=`<b>Vì sao ra ${r.score.toFixed(2)} điểm?</b><span>Điểm đạt: ${r.achieved.toFixed(2)} ÷ ${r.max.toFixed(2)} × 10 = ${r.base.toFixed(2)}</span><span>Thưởng/trừ: ${r.base.toFixed(2)} ${r.bonus>=0?'+':'−'} ${Math.abs(r.bonus).toFixed(2)} = ${r.score.toFixed(2)}</span><span>Hạng ${r.grade} → hệ số KPI ${r.coef.toFixed(1)}</span>`;box.insertAdjacentElement('afterend',node)}
function renderDashboard(){const root=document.querySelector('#dashboardRoot');const rows=Object.keys(groups).map(g=>{const list=members.filter(m=>g==='Leader'?m.leader:m.group===g);const scores=list.map(m=>result(m,g).score);const avg=scores.length?scores.reduce((a,b)=>a+b,0)/scores.length:0;return `<div class="dash-row"><span class="group-tag">${g}</span><div class="dash-bar"><i style="width:${avg*10}%"></i></div><b>${avg.toFixed(2)} / 10</b><span>${list.length} người</span></div>`}).join('');root.innerHTML=`<div class="dashboard-inner"><div class="dash-status"><span>Kỳ ${period.value}</span><strong>${statusLabel(currentStatus())}</strong><span>Vai trò: ${currentRole}</span></div><div class="dash-rows">${rows}</div><div class="dash-legend">Loại đánh giá: nhóm chuyên môn (API/CMS/Ads/Payment/R&D) và Leader được tính riêng.</div></div>`}
function renderDashboardCharts(){const root=document.querySelector('#dashboardRoot');if(!root)return;const teams=Object.keys(groups).map(g=>{const list=members.filter(m=>g==='Leader'?m.leader:m.group===g),avg=list.length?list.reduce((a,m)=>a+result(m,g).score,0)/list.length:0;return {g,avg}}),grades=['A+','A','B+','B','C','D','E'],counts=grades.map(x=>members.filter(m=>result(m,m.group).grade===x).length),maxCount=Math.max(1,...counts);const bars=teams.map((x,i)=>{const y=24+i*32,w=Math.round(x.avg*26);return `<text x="0" y="${y+10}" class="svg-label">${x.g}</text><rect x="58" y="${y}" width="260" height="16" rx="5" class="svg-track"/><rect x="58" y="${y}" width="${w*10}" height="16" rx="5" class="svg-bar"/><text x="328" y="${y+12}" class="svg-value">${x.avg.toFixed(2)}</text>`}).join('');const gradeBars=grades.map((g,i)=>`<div class="grade-chart-row"><b>${g}</b><div><i style="width:${counts[i]/maxCount*100}%"></i></div><span>${counts[i]}</span></div>`).join('');root.insertAdjacentHTML('beforeend',`<div class="dashboard-visuals"><div class="chart-panel"><h3>Điểm trung bình theo team</h3><svg viewBox="0 0 370 ${teams.length*32+24}" role="img" aria-label="Biểu đồ điểm trung bình theo team"><title>Điểm trung bình theo team</title>${bars}</svg><small>Thang điểm 0–10 · Leader dùng bộ tiêu chí riêng</small></div><div class="chart-panel"><h3>Phân bố xếp hạng</h3><div class="grade-chart">${gradeBars}</div><small>Số member theo hạng hiện tại</small></div></div>`)}
function renderAudit(){const root=document.querySelector('#auditRoot'),logs=state.audit||[];root.innerHTML=logs.length?`<div class="audit-list">${logs.slice(0,10).map(x=>`<div class="audit-row"><span>${x.time}</span><b>${x.action}</b><span>${x.role} · ${statusLabel(x.status)}</span></div>`).join('')}</div>`:'<div class="empty audit-empty">Chưa có lịch sử. Các lần lưu và đổi trạng thái sẽ xuất hiện ở đây.</div>'}
function renderTasks(){const root=document.querySelector('#taskRoot'),tasks=state.tasks||[];root.innerHTML=`<div class="task-layout"><form id="taskForm" class="task-form"><label>Tiêu đề task<input name="title" required placeholder="Ví dụ: Tối ưu API playback"></label><label>Member phụ trách<select name="assignee">${members.map(m=>`<option value="${m.id}">${m.name} · ${m.group}</option>`).join('')}</select></label><label>Team<select name="team">${Object.keys(groups).filter(x=>x!=='Leader').map(g=>`<option>${g}</option>`).join('')}</select></label><label>Story Point<input name="points" type="number" min="0" step="0.5" value="1"></label><label>Deadline cam kết<input name="deadline" type="date"></label><label>Loại task<select name="type"><option>Feature</option><option>Bug</option><option>Maintain</option><option>Support</option></select></label><button class="btn btn-primary" type="submit" ${canEdit()?'':'disabled'}>Tạo task local</button></form><div class="task-queue"><div class="queue-title"><b>Task queue</b><span>${tasks.length} task</span></div>${tasks.length?tasks.slice().reverse().map(t=>`<div class="queue-row"><div><b>${t.title}</b><small>${t.assigneeName} · ${t.team} · ${t.points} SP</small></div><span class="queue-status">${t.jiraKey||'Chờ kết nối Jira'}</span></div>`).join(''):'<div class="empty">Chưa có task nào.</div>'}</div></div>`;root.querySelector('#taskForm').onsubmit=e=>{e.preventDefault();if(!canEdit())return;const f=new FormData(e.target),m=members.find(x=>x.id===f.get('assignee'));state.tasks??=[];state.tasks.push({id:Date.now(),title:f.get('title'),assignee:f.get('assignee'),assigneeName:m.name,team:f.get('team'),points:Number(f.get('points'))||0,deadline:f.get('deadline'),type:f.get('type'),jiraKey:null,createdAt:new Date().toLocaleString('vi-VN')});save('Tạo task local');render()}}
function renderSettings(){const root=document.querySelector('#settingsRoot'),s=JSON.parse(localStorage.getItem('backend-jira-settings')||'{}');root.innerHTML=`<form id="jiraSettings" class="settings-form"><div class="settings-status"><span class="status-dot"></span><b>Chưa kết nối Jira</b><span>Cấu hình sẽ được dùng khi backend integration được bật.</span></div><div class="settings-grid"><label>Jira base URL<input name="baseUrl" placeholder="https://company.atlassian.net" value="${s.baseUrl||''}"></label><label>Project key<input name="projectKey" placeholder="BE" value="${s.projectKey||''}"></label><label>Field Story Point<input name="storyPointsField" placeholder="customfield_10016" value="${s.storyPointsField||''}"></label><label>Field deadline cam kết<input name="deadlineField" placeholder="customfield_XXXXX" value="${s.deadlineField||''}"></label><label>Status được tính là Done<input name="doneStatuses" placeholder="Done, Closed, Resolved" value="${s.doneStatuses||'Done, Closed, Resolved'}"></label><label>Kiểu đồng bộ<select name="syncMode"><option value="one-way" ${s.syncMode==='one-way'?'selected':''}>App → Jira trước</option><option value="two-way" ${s.syncMode==='two-way'?'selected':''}>Hai chiều sau khi kết nối</option></select></label></div><div class="settings-note">Không nhập API token tại frontend. Khi kết nối thật, token/OAuth sẽ được lưu ở backend.</div><button class="btn btn-primary" type="submit" ${canEdit()?'':'disabled'}>Lưu cấu hình</button></form>`;root.querySelector('#jiraSettings').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const data=Object.fromEntries(f.entries());localStorage.setItem('backend-jira-settings',JSON.stringify(data));state.audit??=[];state.audit.unshift({time:new Date().toLocaleString('vi-VN'),role:currentRole,action:'Lưu cấu hình Jira',status:currentStatus()});localStorage.setItem(key(),JSON.stringify(state));toast('Đã lưu cấu hình Jira');renderSettings();renderAudit()}}
let criteriaTeam='Payment';let criteriaDraft=null;function renderCriteria(){const root=document.querySelector('#criteriaRoot');if(!root)return;const rows=criteriaDraft||criteriaFor(criteriaTeam).map(c=>({name:c[0],max:c[1]}));root.innerHTML=`<div class="criteria-config"><div class="criteria-toolbar"><label>Team<select id="criteriaTeam">${Object.keys(groups).map(g=>`<option ${g===criteriaTeam?'selected':''}>${g}</option>`).join('')}</select></label><span class="criteria-total">Tổng: <b>${rows.reduce((a,c)=>a+Number(c.max||0),0).toFixed(1)}</b> / 10</span></div><form id="criteriaForm"><div class="criteria-config-list">${rows.map((c,i)=>`<div class="criteria-config-row"><span>${i+1}</span><input data-ci="${i}" data-field="name" value="${c.name}" placeholder="Tên hạng mục"><input data-ci="${i}" data-field="max" type="number" min="0" step="0.1" value="${c.max}"><button type="button" class="remove-criteria" data-remove="${i}">×</button></div>`).join('')}</div><div class="criteria-actions"><button type="button" class="btn btn-ghost" id="addCriteria">+ Thêm hạng mục</button><button type="button" class="btn btn-ghost" id="restoreCriteria">Khôi phục mặc định</button><button class="btn btn-primary" type="submit" ${canEdit()?'':'disabled'}>Lưu tiêu chí</button></div></form><div class="settings-note">Mỗi hạng mục có thể thay đổi tên và trọng số. Tổng trọng số phải đúng 10 điểm; công thức tổng hợp sẽ tự dùng cấu hình mới.</div></div>`;root.querySelector('#criteriaTeam').onchange=e=>{criteriaTeam=e.target.value;criteriaDraft=null;renderCriteria()};root.querySelectorAll('[data-ci]').forEach(i=>i.oninput=()=>{criteriaDraft??=rows.map(x=>({...x}));criteriaDraft[Number(i.dataset.ci)][i.dataset.field]=i.dataset.field==='max'?Number(i.value)||0:i.value;renderCriteria()});root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{criteriaDraft??=rows.map(x=>({...x}));criteriaDraft.splice(Number(b.dataset.remove),1);renderCriteria()});root.querySelector('#addCriteria').onclick=()=>{criteriaDraft??=rows.map(x=>({...x}));criteriaDraft.push({name:'Hạng mục mới',max:0});renderCriteria()};root.querySelector('#restoreCriteria').onclick=()=>{delete customCriteria[criteriaTeam];localStorage.setItem('backend-kpi-criteria',JSON.stringify(customCriteria));groups[criteriaTeam].criteria=groups[criteriaTeam].criteria;criteriaDraft=null;renderCriteria();toast('Đã khôi phục tiêu chí mặc định')};root.querySelector('#criteriaForm').onsubmit=e=>{e.preventDefault();const finalRows=(criteriaDraft||rows).filter(x=>x.name.trim());const total=finalRows.reduce((a,c)=>a+Number(c.max||0),0);if(Math.abs(total-10)>.001){toast(`Không thể lưu: tổng trọng số đang là ${total.toFixed(1)}, cần bằng 10`);return}customCriteria[criteriaTeam]=finalRows.map(x=>[x.name,Number(x.max)]);groups[criteriaTeam].criteria=customCriteria[criteriaTeam];localStorage.setItem('backend-kpi-criteria',JSON.stringify(customCriteria));criteriaDraft=null;save('Cập nhật tiêu chí '+criteriaTeam);render()}}
let autoDemoReport=null;function demoEval(m,group,index){const g=groups[group],pattern=.55+Math.random()*.45,scores=g.criteria.map(c=>Math.round(c[1]*pattern*10)/10),achieved=scores.reduce((a,b)=>a+b,0),max=g.criteria.reduce((a,c)=>a+c[1],0),base=achieved/max*10,bonus=Math.random()<.12?.5:Math.random()<.08?-.5:0,score=Math.max(0,Math.min(10,base+bonus)),grade=score===10?'A+':score>=9.7?'A':score>=9.4?'B+':score>=9?'B':score>=8?'C':score>=7.5?'D':'E',coef=score===10?1.4:score>=9.7?1.3:score>=9.4?1.2:score>=9?1.1:score>=8?1:score>=7.5?.8:.6;return {m,group,scores,achieved,max,base,bonus,score,grade,coef}}
let mockJiraTasks=[];function runJiraSimulation(){mockJiraTasks=[];let n=1;members.forEach((m,i)=>{const count=2+Math.floor(Math.random()*4),completion=.55+Math.random()*.45;for(let j=0;j<count;j++){const points=[1,2,3,5][Math.floor(Math.random()*4)],done=Math.random()<completion;mockJiraTasks.push({key:`MOCK-BE-${String(n++).padStart(3,'0')}`,title:`${['API','CMS','Ads','Payment','R&D'][Math.floor(Math.random()*5)]} demo task ${j+1}`,member:m,points,status:done?'Done':'In Progress',deadline:`2026-07-${String(10+j).padStart(2,'0')}`,completedAt:done?`2026-07-${String(9+j).padStart(2,'0')}`:null})}});renderJiraSim()}
function syncJiraSimulation(){if(!mockJiraTasks.length)return;members.forEach((m,i)=>{const tasks=mockJiraTasks.filter(t=>t.member.id===m.id),committed=tasks.length,closed=tasks.filter(t=>t.status==='Done').length,committedPoints=tasks.reduce((a,t)=>a+t.points,0),deliveredPoints=tasks.filter(t=>t.status==='Done').reduce((a,t)=>a+t.points,0),rate=committed?closed/committed:0;state[m.id]??={};state[m.id].workload={committed,closed,committedPoints,deliveredPoints};const group=m.group,g=groups[group],pattern=[.95,.88,.8,.72,.64][i%5];state[m.id][group]??={};state[m.id][group].scores=g.criteria.map((c,k)=>{if(k===0){if(rate>=.9)return c[1];if(rate>=.75)return c[1]*.6;if(rate>=.6)return c[1]*.267;return 0}return Math.round(c[1]*pattern*10)/10});if(m.leader){const lg=groups.Leader;state[m.id].Leader??={};state[m.id].Leader.scores=lg.criteria.map(c=>Math.round(c[1]*pattern*10)/10)}});save('Sync dữ liệu mock Jira vào KPI');renderJiraSim();render()}
function renderJiraSim(){const root=document.querySelector('#jiraSimRoot');if(!root)return;if(!mockJiraTasks.length){root.innerHTML='<div class="jira-sim-start"><div><b>Giả lập Jira → KPI</b><span>Tạo issue mock cho toàn bộ member, gán Story Point, trạng thái Done/In Progress rồi sync vào kỳ đánh giá.</span></div><button class="btn btn-outline" id="runJiraSim">Tạo task Jira giả lập</button></div>';root.querySelector('#runJiraSim').onclick=runJiraSimulation;return}const closed=mockJiraTasks.filter(t=>t.status==='Done').length,points=mockJiraTasks.reduce((a,t)=>a+t.points,0),delivered=mockJiraTasks.filter(t=>t.status==='Done').reduce((a,t)=>a+t.points,0);root.innerHTML=`<div class="jira-sim"><div class="jira-sim-head"><div><b>Mock Jira đã tạo ${mockJiraTasks.length} issue</b><span>${closed} Done · ${mockJiraTasks.length-closed} In Progress · ${delivered}/${points} Story Point đạt</span></div><div><button class="btn btn-primary" id="syncJiraSim">Sync vào KPI</button><button class="btn btn-ghost" id="resetJiraSim">Xóa mock</button></div></div><div class="jira-table-wrap"><table class="auto-table"><thead><tr><th>Issue</th><th>Task</th><th>Member</th><th>Story Point</th><th>Status</th><th>Deadline</th></tr></thead><tbody>${mockJiraTasks.slice(0,40).map(t=>`<tr><td><b>${t.key}</b></td><td>${t.title}</td><td>${t.member.name}</td><td>${t.points}</td><td><span class="queue-status ${t.status==='Done'?'done':''}">${t.status}</span></td><td>${t.deadline}</td></tr>`).join('')}</tbody></table></div><div class="jira-sim-note">Sau khi sync, hệ thống cập nhật workload, tiêu chí hoàn thành task và tính lại điểm /10, xếp hạng, hệ số KPI.</div></div>`;root.querySelector('#syncJiraSim').onclick=syncJiraSimulation;root.querySelector('#resetJiraSim').onclick=()=>{mockJiraTasks=[];renderJiraSim()}}
function runAutoDemo(){const rows=[];members.forEach((m,i)=>rows.push(demoEval(m,m.group,i)));members.filter(m=>m.leader).forEach((m,i)=>rows.push(demoEval(m,'Leader',i+30)));autoDemoReport=rows;renderAutoDemo()}
function renderAutoDemo(){const root=document.querySelector('#autoDemoRoot');if(!root)return;if(!autoDemoReport){root.innerHTML='<div class="auto-demo-start"><div><b>Demo tự động toàn bộ member</b><span>Tạo dữ liệu mẫu, chấm điểm từng tiêu chí và xuất bản đánh giá chi tiết mà không thay đổi dữ liệu thật.</span></div><button class="btn btn-primary" id="runAutoDemo">Chạy demo tự động</button></div>';root.querySelector('#runAutoDemo').onclick=runAutoDemo;return}const avg=autoDemoReport.reduce((a,r)=>a+r.score,0)/autoDemoReport.length,top=autoDemoReport.slice().sort((a,b)=>b.score-a.score)[0],low=autoDemoReport.slice().sort((a,b)=>a.score-b.score)[0];root.innerHTML=`<div class="auto-demo-report"><div class="auto-report-head"><div><b>Bản đánh giá demo chi tiết</b><span>${autoDemoReport.length} lượt đánh giá mẫu · không ảnh hưởng dữ liệu thật</span></div><button class="btn btn-ghost" id="rerunDemo">Chạy lại</button></div><div class="auto-report-summary"><span>Điểm TB <b>${avg.toFixed(2)}</b></span><span>Cao nhất <b>${top.m.name} · ${top.score.toFixed(2)}</b></span><span>Cần cải thiện <b>${low.m.name} · ${low.score.toFixed(2)}</b></span></div><div class="auto-table-wrap"><table class="auto-table"><thead><tr><th>Member</th><th>Loại</th><th>Điểm đạt</th><th>Điểm /10</th><th>Hạng</th><th>Hệ số</th><th>Giải thích</th></tr></thead><tbody>${autoDemoReport.map(r=>`<tr><td><b>${r.m.name}</b><small>${r.m.id}</small></td><td>${r.group==='Leader'?'Leader':'Chuyên môn · '+r.group}</td><td>${r.achieved.toFixed(1)} / ${r.max.toFixed(1)}</td><td><strong>${r.score.toFixed(2)}</strong></td><td>${r.grade}</td><td>${r.coef.toFixed(1)}</td><td>(${r.achieved.toFixed(1)} ÷ ${r.max.toFixed(1)}) × 10 = ${r.base.toFixed(2)}; thưởng/trừ ${r.bonus>=0?'+':''}${r.bonus.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></div>`;root.querySelector('#rerunDemo').onclick=runAutoDemo}
let activeModule='dashboard';function toggleModules(){const visible={dashboard:['stats','dashboardCard'],evaluation:['evaluationToolbar','evaluationContent'],comparison:['evaluationToolbar','evaluationContent'],tasks:['taskCard'],demo:['demoCard'],formula:['formulaExplainer'],audit:['auditCard'],settings:['settingsCard']}[activeModule]||[];document.querySelectorAll('.module-section').forEach(el=>{el.style.display=visible.includes(el.id)?'':'none'});document.querySelectorAll('.module-btn').forEach(b=>b.classList.toggle('active',b.dataset.module===activeModule))}
