function timelineKey(){return `backend-kpi-timeline-${period.value}`}function timelineDefaults(){const [y,mo]=period.value.split('-').map(Number),d=n=>`${y}-${String(mo).padStart(2,'0')}-${String(n).padStart(2,'0')}`;return{start:d(1),memberDeadline:d(10),leaderDeadline:d(17),lockDate:d(20)}}function renderTimeline(){const root=document.querySelector('#timelineRoot');if(!root)return;const saved=JSON.parse(localStorage.getItem(timelineKey())||'{}'),cfg={...timelineDefaults(),...saved},steps=[['start','Mở kỳ đánh giá','Member bắt đầu cập nhật điểm và minh chứng'],['memberDeadline','Hạn member hoàn tất','Member lưu nháp hoặc hoàn tất đánh giá'],['leaderDeadline','Hạn Leader review','Leader kiểm tra điểm, task và minh chứng'],['lockDate','Khóa kỳ & xuất báo cáo','Admin khóa dữ liệu và chốt kết quả']],today=new Date();today.setHours(0,0,0,0);const current=currentStatus(),items=steps.map((s,i)=>{const date=new Date(`${cfg[s[0]]}T00:00:00`),done=i===0?today>=date:(i===1?current!=='draft'&&today>=date:i===2?(current==='approved'||current==='locked')&&today>=date:current==='locked'||today>=date&&current==='locked');const overdue=today>date&&!done;return{...s,date,done,overdue}}),doneCount=items.filter(x=>x.done).length,reminders=[];if(current==='draft')reminders.push(`Còn ${members.length} member cần hoàn tất hoặc cập nhật điểm`);if(current==='submitted')reminders.push('Có dữ liệu đã gửi, Leader cần review');if(current==='approved')reminders.push('Admin cần khóa kỳ để chốt báo cáo');items.forEach(x=>{if(x.overdue)reminders.push(`${x[1]} đã quá hạn (${x.date.toLocaleDateString('vi-VN')})`)});root.innerHTML=`<div class="timeline-layout"><form id="timelineForm" class="timeline-form"><div class="timeline-form-head"><b>Mốc thời gian</b><span>Kỳ ${period.value}</span></div><label>Bắt đầu kỳ<input name="start" type="date" value="${cfg.start}"></label><label>Hạn member hoàn tất<input name="memberDeadline" type="date" value="${cfg.memberDeadline}"></label><label>Hạn Leader review<input name="leaderDeadline" type="date" value="${cfg.leaderDeadline}"></label><label>Ngày khóa kỳ<input name="lockDate" type="date" value="${cfg.lockDate}"></label><button class="btn btn-primary" type="submit" ${canEdit()?'':'disabled'}>Lưu timeline</button></form><div class="timeline-side"><div class="timeline-progress"><div><b>Tiến độ kỳ</b><strong>${Math.round(doneCount/items.length*100)}%</strong></div><div class="timeline-progress-track"><i style="width:${doneCount/items.length*100}%"></i></div><small>${doneCount}/${items.length} mốc đã hoàn tất · Trạng thái: ${statusLabel(current)}</small></div><div class="reminder-box"><b>Lịch nhắc cần xử lý</b>${reminders.length?reminders.map(x=>`<div class="reminder-item">! ${x}</div>`).join(''):'<div class="reminder-ok">✓ Chưa có nhắc việc quá hạn</div>'}</div></div></div><div class="timeline-track">${items.map(x=>`<div class="timeline-step ${x.done?'is-done':''} ${x.overdue?'is-overdue':''}"><div class="timeline-dot">${x.done?'✓':x.overdue?'!':'·'}</div><div><b>${x[1]}</b><span>${x[2]}</span><small>${x.date.toLocaleDateString('vi-VN')}${x.overdue?' · Quá hạn':''}</small></div></div>`).join('')}</div>`;root.querySelector('#timelineForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const data=Object.fromEntries(f.entries());localStorage.setItem(timelineKey(),JSON.stringify(data));save('Cập nhật timeline kỳ');renderTimeline();toast('Đã lưu timeline và lịch nhắc')}}
