const _renderEditorModal=renderEditor;renderEditor=function(){_renderEditorModal();const card=document.querySelector('.editor-card'),m=members.find(x=>x.id===selectedId);if(!card)return;let backdrop=document.querySelector('#editorModalBackdrop');if(!backdrop){backdrop=document.createElement('div');backdrop.id='editorModalBackdrop';backdrop.className='editor-modal-backdrop';document.body.appendChild(backdrop);backdrop.onclick=()=>{selectedId=null;render()}}card.classList.toggle('editor-modal-open',!!m);backdrop.classList.toggle('hidden',!m);if(m&&!card.querySelector('#editorClose')){const close=document.createElement('button');close.id='editorClose';close.className='editor-close';close.type='button';close.setAttribute('aria-label','Đóng cửa sổ nhập điểm');close.textContent='×';card.querySelector('.card-head').appendChild(close);close.onclick=()=>{selectedId=null;render()}}};render();
